OPTIONAL_VEHICLE_FIELDS = (
    "max_ice_conc",
    "min_depth",
    "max_wave",
    "excluded_zones",
    "neighbour_splitting",
    "beam",
    "hull_type",
    "force_limit",
)


def existing_meshes_to_vehicle_meshes(apps, schema_editor):
    """Every mesh before this migration is a vessel mesh: give it a VehicleMesh
    row with the same id, and set the vehicle and vehicle mesh of the routes
    calculated on it."""
    Mesh = apps.get_model("route_api", "Mesh")
    Vehicle = apps.get_model("route_api", "Vehicle")
    VehicleMesh = apps.get_model("route_api", "VehicleMesh")
    Route = apps.get_model("route_api", "Route")

    for mesh in Mesh.objects.only("id", "json").iterator():
        vessel_info = ((mesh.json or {}).get("config") or {}).get("vessel_info")
        if not vessel_info or not vessel_info.get("vessel_type"):
            continue

        vehicle = Vehicle.objects.filter(vessel_type=vessel_info["vessel_type"]).first()
        if vehicle is None:
            if vessel_info.get("max_speed") is None or not vessel_info.get("unit"):
                continue
            vehicle = Vehicle.objects.create(
                vessel_type=vessel_info["vessel_type"],
                max_speed=vessel_info["max_speed"],
                unit=vessel_info["unit"],
                created_by="migration",
                **{
                    f: vessel_info[f]
                    for f in OPTIONAL_VEHICLE_FIELDS
                    if f in vessel_info
                },
            )

        # raw save: only insert the child row, the Mesh row already exists
        VehicleMesh(mesh_ptr_id=mesh.id, vehicle=vehicle).save_base(raw=True)
        Route.objects.filter(mesh_id=mesh.id).update(
            vehicle=vehicle, vehicle_mesh_id=mesh.id
        )


